// definition order for ambiguous messages: need to match observed
// Observed orders:
// --s -> scale, svg, svg-font-url
// --t -> transparent, tabs
// --h -> help, html
// --no, --n, --no- -> no-shadows, no-antialias, no-separation
// --sv -> svg, svg-font-url
// --no-s -> no-shadows, no-separation
// We need a global order that produces these when filtered.
// Let's define order as: no-shadows, no-antialias, no-separation, background, debug, encoding, help, html, overwrite, round-corners, scale, svg, svg-font-url, transparent, tabs, verbose, fixed-slope
// Check: --s matches scale, svg, svg-font-url in this order? scale(11), svg(12), svg-font-url(13) -> yes.
// --t matches transparent(14), tabs(15) -> yes.
// --h matches help(7), html(8?) Wait in our order help before html? We have help(7), html(8)? Actually list above has help then html? Let's set help before html to match observed help,html.
// --no matches no-shadows, no-antialias, no-separation in order -> yes if we put shadows first.
// --sv matches svg, svg-font-url -> yes.
// --no-s matches no-shadows, no-separation (antialias doesn't start with no-s) -> order shadows, separation -> yes.

var ambiguousOrder = []string{
	"no-shadows", "no-antialias", "no-separation",
	"background", "debug", "encoding", "help", "html",
	"overwrite", "round-corners", "scale", "svg", "svg-font-url",
	"transparent", "tabs", "verbose", "fixed-slope",
}

var shortToDef = map[byte]*OptionDef{}
var longToDef = map[string]*OptionDef{}

func init() {
	for i := range optionDefs {
		d := &optionDefs[i]
		if d.Short != 0 {
			shortToDef[d.Short] = d
		}
		longToDef[d.Long] = d
	}
}

type ParsedOption struct {
	Def   *OptionDef
	Value string // for HasArg, the value; for flag, ""
	Raw   string // original?
}

func findLongMatches(prefix string) []*OptionDef {
	var res []*OptionDef
	// exact match takes precedence
	if d, ok := longToDef[prefix]; ok {
		return []*OptionDef{d}
	}
	// prefix matches in ambiguousOrder
	for _, name := range ambiguousOrder {
		if strings.HasPrefix(name, prefix) {
			res = append(res, longToDef[name])
		}
	}
	return res
}

func isValidShort(c byte) bool {
	_, ok := shortToDef[c]
	return ok
}

// isOptionLike checks if arg would be considered an option (for missing arg detection)
// Returns: 0 = not option (consume as value), 1 = valid option (missing), 2 = ambiguous (report ambiguous), 3 = unrecognized? Actually unrecognized is not option for consumption? For -b -z, -z is unrecognized but consumed as value, so return 0.
// For -b --s (ambiguous), return 2.
// For -b -Az (invalid combined but first char valid), return 1 (missing).
// For -b --invalid (unrecognized long), return 0.
// For -b -back (valid long prefix), return 1.
// For --, return 0 (consume as value).
// For -, return 0.
func classifyNextAsOption(arg string) (int, string, []*OptionDef) {
	if arg == "--" || arg == "-" {
		return 0, "", nil
	}
	if strings.HasPrefix(arg, "--") {
		// double dash
		rest := arg[2:]
		// split on =
		eq := strings.Index(rest, "=")
		var name string
		if eq >= 0 {
			name = rest[:eq]
		} else {
			name = rest
		}
		if name == "" {
			// "--=x" or "--"? "--" already handled. "--=x" => name ""? What happens? Likely unrecognized "--=x"? Let's treat as not option? Actually "--=x" starts with --, name empty, no longs start with ""? All start with "" (empty prefix matches all) => ambiguous? But commons-cli probably treats "--" with empty as... Let's test later. For now, treat as unrecognized (0).
			return 0, "", nil
		}
		matches := findLongMatches(name)
		if len(matches) == 0 {
			return 0, "", nil // unrecognized, consume as value
		} else if len(matches) > 1 {
			return 2, arg, matches // ambiguous
		} else {
			return 1, "", matches // valid
		}
	} else if strings.HasPrefix(arg, "-") && len(arg) > 1 {
		// single dash
		rest := arg[1:]
		// check for long prefix match (only if len>1? For "-s" len1, it's short, not long prefix? But "-s" could be prefix of scale,svg etc. However exact short takes precedence? Earlier "-s" with value was treated as short, not ambiguous. So for single char rest that is valid short, treat as valid short (1), not long prefix.
		// For longer rest, try long prefix first.
		if len(rest) == 1 {
			if isValidShort(rest[0]) {
				return 1, "", nil
			} else {
				return 0, "", nil
			}
		} else {
			// len >1, try long prefix
			// Note: single-dash does NOT split on = (as observed -svg=x is short s with vg=x). So use whole rest for matching, including =.
			matches := findLongMatches(rest)
			// But findLongMatches with rest containing = will never match (since longs don't contain =), so 0 matches, fall through to short check.
			// However, need to handle case where rest is exact long? e.g., "-svg" => rest "svg" exact matches svg => valid.
			// "-sv" => rest "sv" prefix matches svg, svg-font-url => ambiguous.
			if len(matches) > 1 {
				return 2, arg, matches
			} else if len(matches) == 1 {
				// Check if this single match is exact? Or prefix? For "-sc" (sc prefix of scale), matches scale alone => valid.
				return 1, "", matches
			} else {
				// no long match, check first char short
				if isValidShort(rest[0]) {
					return 1, "", nil
				} else {
					return 0, "", nil
				}
			}
		}
	} else {
		return 0, "", nil
	}
}

func ambiguousMessage(opt string, matches []*OptionDef) string {
	var names []string
	for _, m := range matches {
		names = append(names, "'"+m.Long+"'")
	}
	return fmt.Sprintf("Ambiguous option: '%s'  (could be: %s)\n", opt, strings.Join(names, ", "))
}

GOEOF
cat main.go | head -n 50"}

