func parseArgs(args []string) ([]ParsedOption, []string, string, string, int) {
	// Returns: options in order, positionals, stdoutUsage ("" or helpUpper), stderrMsg, exitCode (0 if no error, 2 if error)
	// On error, stdoutUsage is helpUpper (to be printed to stdout), stderrMsg to stderr, exit 2.
	var opts []ParsedOption
	var positionals []string
	i := 0
	terminator := false
	for i < len(args) {
		arg := args[i]
		if terminator {
			positionals = append(positionals, arg)
			i++
			continue
		}
		if arg == "--" {
			terminator = true
			i++
			continue
		}
		if arg == "-" {
			positionals = append(positionals, arg)
			i++
			continue
		}
		if strings.HasPrefix(arg, "--") {
			// double dash
			rest := arg[2:]
			eqIdx := strings.Index(rest, "=")
			var name, valPart string
			hasEq := false
			if eqIdx >= 0 {
				name = rest[:eqIdx]
				valPart = rest[eqIdx+1:]
				hasEq = true
			} else {
				name = rest
			}
			if name == "" {
				// e.g., "--=x" or "--"? "--" handled. For "--=x", treat as unrecognized?
				return nil, nil, helpUpper, fmt.Sprintf("Unrecognized option: %s\n", arg), 2
			}
			matches := findLongMatches(name)
			if len(matches) == 0 {
				return nil, nil, helpUpper, fmt.Sprintf("Unrecognized option: %s\n", arg), 2
			} else if len(matches) > 1 {
				return nil, nil, helpUpper, ambiguousMessage(arg, matches), 2
			}
			def := matches[0]
			if def.HasArg {
				var val string
				if hasEq {
					val = valPart
				} else {
					// need next arg
					if i+1 >= len(args) {
						// missing
						shortOrLong := def.Long
						if def.Short != 0 {
							shortOrLong = string([]byte{def.Short})
						}
						return nil, nil, helpUpper, fmt.Sprintf("Missing argument for option: %s\n", shortOrLong), 2
					}
					next := args[i+1]
					// classify next
					cls, ambOpt, ambMatches := classifyNextAsOption(next)
					if cls == 2 {
						return nil, nil, helpUpper, ambiguousMessage(ambOpt, ambMatches), 2
					} else if cls == 1 {
						shortOrLong := def.Long
						if def.Short != 0 {
							shortOrLong = string([]byte{def.Short})
						}
						return nil, nil, helpUpper, fmt.Sprintf("Missing argument for option: %s\n", shortOrLong), 2
					} else {
						val = next
						i++ // consume next
					}
				}
				opts = append(opts, ParsedOption{Def: def, Value: val})
			} else {
				// no arg
				if hasEq {
					opts = append(opts, ParsedOption{Def: def})
					// value part becomes positional
					positionals = append(positionals, valPart)
				} else {
					opts = append(opts, ParsedOption{Def: def})
				}
			}
			i++
			continue
		} else if strings.HasPrefix(arg, "-") && len(arg) > 1 {
			rest := arg[1:]
			// Try long prefix first if len>1
			if len(rest) > 1 {
				matches := findLongMatches(rest)
				if len(matches) > 1 {
					return nil, nil, helpUpper, ambiguousMessage(arg, matches), 2
				} else if len(matches) == 1 {
					def := matches[0]
					if def.HasArg {
						// need next arg (single-dash long does not support = or attached)
						if i+1 >= len(args) {
							shortOrLong := def.Long
							if def.Short != 0 {
								shortOrLong = string([]byte{def.Short})
							}
							return nil, nil, helpUpper, fmt.Sprintf("Missing argument for option: %s\n", shortOrLong), 2
						}
						next := args[i+1]
						cls, ambOpt, ambMatches := classifyNextAsOption(next)
						if cls == 2 {
							return nil, nil, helpUpper, ambiguousMessage(ambOpt, ambMatches), 2
						} else if cls == 1 {
							shortOrLong := def.Long
							if def.Short != 0 {
								shortOrLong = string([]byte{def.Short})
							}
							return nil, nil, helpUpper, fmt.Sprintf("Missing argument for option: %s\n", shortOrLong), 2
						} else {
							opts = append(opts, ParsedOption{Def: def, Value: next})
							i += 2
							continue
						}
					} else {
						opts = append(opts, ParsedOption{Def: def})
						i++
						continue
					}
				}
				// else fall through to short handling
			}
			// short handling: iterate chars
			// rest could be 1 char or multiple
			consumedNext := false
			failed := false
			for j := 0; j < len(rest); j++ {
				c := rest[j]
				def, ok := shortToDef[c]
				if !ok {
					return nil, nil, helpUpper, fmt.Sprintf("Unrecognized option: %s\n", arg), 2
				}
				if def.HasArg {
					var val string
					if j+1 < len(rest) {
						// attached
						val = rest[j+1:]
						opts = append(opts, ParsedOption{Def: def, Value: val})
					} else {
						// need next arg
						if i+1 >= len(args) {
							return nil, nil, helpUpper, fmt.Sprintf("Missing argument for option: %s\n", string([]byte{c})), 2
						}
						next := args[i+1]
						cls, ambOpt, ambMatches := classifyNextAsOption(next)
						if cls == 2 {
							return nil, nil, helpUpper, ambiguousMessage(ambOpt, ambMatches), 2
						} else if cls == 1 {
							return nil, nil, helpUpper, fmt.Sprintf("Missing argument for option: %s\n", string([]byte{c})), 2
						} else {
							val = next
							opts = append(opts, ParsedOption{Def: def, Value: val})
							consumedNext = true
						}
					}
					break // after arg-taking short, rest consumed
				} else {
					opts = append(opts, ParsedOption{Def: def})
					// continue to next char
					if j == len(rest)-1 {
						// done
					}
				}
				if failed {
					break
				}
			}
			if consumedNext {
				i += 2
			} else {
				i++
			}
			continue
		} else {
			positionals = append(positionals, arg)
			i++
			continue
		}
	}
	return opts, positionals, "", "", 0
}

