func drawLine(img *image.RGBA, x0, y0, x1, y1 int, col color.RGBA, dashed bool) {
	// Bresenham with dash 5,5 if dashed
	dx := x1 - x0
	dy := y1 - y0
	steps := dx
	if steps < 0 {
		steps = -steps
	}
	if dy < 0 {
		if -dy > steps {
			steps = -dy
		}
	} else {
		if dy > steps {
			steps = dy
		}
	}
	if steps == 0 {
		if x0 >= 0 && y0 >= 0 && x0 < img.Bounds().Dx() && y0 < img.Bounds().Dy() {
			img.SetRGBA(x0, y0, col)
		}
		return
	}
	for i := 0; i <= steps; i++ {
		if dashed {
			// dash 5 on, 5 off
			if (i/5)%2 == 1 {
				continue
			}
		}
		x := x0 + dx*i/steps
		y := y0 + dy*i/steps
		if x >= 0 && y >= 0 && x < img.Bounds().Dx() && y < img.Bounds().Dy() {
			img.SetRGBA(x, y, col)
		}
	}
}

